const fs = require("fs");
const path = require("path");
const { pathToFileURL } = require("url");
const root = "/w/covinclude";
fs.rmSync(root, { recursive: true, force: true });
fs.mkdirSync(path.join(root, "src"), { recursive: true });
fs.writeFileSync(path.join(root, "src", "a.js"), "export const a = 1\n");
fs.writeFileSync(path.join(root, "src-file-in-root.js"), "export const b = 2\n");
// A minimal custom coverage provider built on vitest's public BaseCoverageProvider.
fs.writeFileSync(path.join(root, "provider.mjs"), [
  "const Base = globalThis.__ludionBaseCoverageProvider",
  "class Provider extends Base {",
  "  name = 'custom'",
  "  initialize(ctx) { this.version = ctx.version; this._initialize(ctx) }",
  "  resolveOptions() { return this.options }",
  "  async clean() {}",
  "  onAfterSuiteRun() {}",
  "  async reportCoverage() {}",
  "}",
  "export default { getProvider() { return new Provider() } }",
].join("\n") + "\n");
setTimeout(() => { console.error("ERROR: timed out"); process.exit(2); }, 80000).unref();
(async () => {
  let inDir, sibling;
  try {
    const node = await import(pathToFileURL("/w/node_modules/vitest/dist/node.js").href);
    globalThis.__ludionBaseCoverageProvider = node.BaseCoverageProvider;
    const vitest = await node.createVitest("test", {
      root,
      config: false,
      watch: false,
      include: ["dont-match-anything"],
      coverage: {
        enabled: true,
        provider: "custom",
        customProviderModule: path.join(root, "provider.mjs"),
        include: ["src"],
      },
    });
    await vitest.initCoverageProvider();
    const provider = vitest.coverageProvider;
    if (!provider || typeof provider.isIncluded !== "function") {
      console.error("ERROR: custom coverage provider was not created");
      process.exit(2);
    }
    inDir = provider.isIncluded(path.join(root, "src", "a.js"));
    sibling = provider.isIncluded(path.join(root, "src-file-in-root.js"));
    await vitest.close();
  } catch (e) {
    console.error("ERROR: " + (e && e.stack || e));
    process.exit(2);
  }
  console.log("coverage.include ['src']: src/a.js included=" + inDir + ", src-file-in-root.js included=" + sibling);
  if (inDir !== true) {
    console.error("ERROR: src/a.js was not included");
    process.exit(2);
  }
  if (sibling === false) {
    console.log("PASS: coverage.include ['src'] matches only files inside the src directory");
    process.exit(0);
  }
  if (sibling === true) {
    console.error("FAIL: coverage.include ['src'] also included src-file-in-root.js outside the src directory");
    process.exit(1);
  }
  console.error("ERROR: unexpected isIncluded result " + sibling);
  process.exit(2);
})();

